package tmmodern;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import com.google.gson.*;
class ResourceContractTest {
    Path root=Path.of("src/generated/resources");JsonObject object(Path p)throws Exception{return JsonParser.parseString(Files.readString(p)).getAsJsonObject();}
    @Test void originalTexturesAreExternalAndEveryModelResolves()throws Exception{var manifest=object(root.resolve("data/taintedmagic/thaumcraft/original_resources.json"));assertEquals("2fbf1f56a1b8cbdfb80296904e4a5a8f6ac585b0423053a170b49259193da824",manifest.get("sha256").getAsString());var mapping=manifest.getAsJsonObject("mapping");try(var files=Files.walk(root.resolve("assets/taintedmagic/models"))){for(var path:files.filter(p->p.toString().endsWith(".json")).toList()){var data=object(path);if(!data.has("textures"))continue;for(var e:data.getAsJsonObject("textures").entrySet()){String texture=e.getValue().getAsString();if(texture.startsWith("taintedmagic:"))assertTrue(mapping.has("assets/"+texture.replace(":","/textures/")+".png"),path+" -> "+texture);}}}}
    @Test void researchPagesReferenceRealRecipes()throws Exception{var pages=object(root.resolve("data/taintedmagic/research_pages/core.json"));var catalog=object(root.resolve("data/taintedmagic/research_catalog/core.json"));var keys=new java.util.HashSet<String>();for(var category:catalog.getAsJsonArray("categories"))for(var r:category.getAsJsonObject().getAsJsonArray("research"))if(!r.getAsJsonObject().has("isStub")||!r.getAsJsonObject().get("isStub").getAsBoolean())keys.add(r.getAsJsonObject().get("key").getAsString());var pageKeys=new java.util.HashSet<String>();for(var r:pages.getAsJsonArray("entries"))pageKeys.add(r.getAsJsonObject().get("key").getAsString());assertEquals(keys,pageKeys,"Each current research has pages");for(var research:pages.getAsJsonArray("entries"))for(var p:research.getAsJsonObject().getAsJsonArray("pages")){var page=p.getAsJsonObject();if(!page.has("recipe"))continue;for(var k:page.getAsJsonObject("recipe").getAsJsonArray("keys"))assertTrue(Files.exists(root.resolve("data/taintedmagic/recipes/"+k.getAsString().split(":")[1]+".json")));}}
    @Test void legacyFocusUpgradeCostsAreRetained()throws Exception{var list=JsonParser.parseString(Files.readString(root.resolve("data/taintedmagic/thaumcraft/focus_upgrades.json"))).getAsJsonArray();assertEquals(5,list.size());assertEquals(7,list.get(4).getAsJsonObject().getAsJsonArray("aspects").size());}
}
